agent-task.code:
// hint: 공개 API 전체다. 타입 이름, 메서드 이름, 인자 레이블, 반환 타입이 계약이다.
//       내부 구현, 파일 분할, private 헬퍼는 실행하는 쪽이 정한다.
internal import CNTFS3G    // 실제 타깃. 공개 API에 C 타입이 새어 나가지 않는다.
import Foundation          // URL, Date

public struct NTFSFormatOptions {
    public var label: String = ""                // 금지 문자 검사, 32 UTF-16 유닛 이하 (P6, §3)
    public var clusterSize: Int = 4096           // 항상 -c로 넘긴다 (P6)
    public var sectorSize: Int = 512             // 512 또는 4096. 대상 디스크의 논리 섹터 크기
    public var partitionStartSector: UInt64 = 0  // BPB hidden sectors (F3)
}

public struct NTFSFileTimes { creation: Date; modification: Date; access: Date }   // P9
public enum NTFSItemKind { case file, directory }
public struct NTFSDirectoryEntry { name: String; kind: NTFSItemKind }
public struct NTFSItemAttributes { kind: NTFSItemKind; size: Int64; times: NTFSFileTimes }
public struct NTFSCopyProgress { completedBytes: Int64; totalBytes: Int64; currentPath: String }
public struct NTFSCopySummary { files: Int; directories: Int; bytes: Int64 }

public enum NTFS3GError: Error {
    case invalidPath(String)             // P2
    case invalidName(String)             // D12, P2
    case notFound(String)
    case alreadyExists(String)           // D14, P3
    case notADirectory(String)
    case isADirectory(String)
    case unsupportedFileType(URL)        // D15
    case readOnlyVolume
    case volumeClosed                    // P5
    case formatFailed(status: Int32)     // mkntfs 종료 코드
    case posix(operation: String, path: String?, errno: Int32)
}

public final class NTFSVolume {          // non-Sendable (D8)
    public enum Mode { case readOnly, readWrite }

    public var label: String { get }
    public var clusterSize: Int { get }
    public var totalBytes: Int64 { get }
    public var freeBytes: Int64 { get }  // 호출 시점의 값 (F18)

    imagine public static func format(path: String, options: NTFSFormatOptions = .init()) throws {
        requirements(`
            이미 최종 크기로 존재하는 파일을 NTFS로 포맷한다. ntfs3g_mkntfs를 P6의 인자로 부른다.
            레이블을 먼저 검증한다. 종료 코드가 0이 아니면 formatFailed.
        `);
        ensure(/* 64 MiB 파일 */ format(p, .init(label: "SNAKESTICK")) 후 NTFSVolume(path: p, mode: .readOnly).label == "SNAKESTICK");
        ensure(format(p, .init(sectorSize: 4096)) 후 readOnly 마운트가 성공한다);
        ensure(존재하지 않는 경로에 format → throws);
        ensure(format(p, .init(label: "A:B")) → throws NTFS3GError.invalidName);
        ensure(format 전후 setlocale(LC_ALL, nil)의 문자열이 같다, "F16, P7");
    }

    imagine public static func estimatedVolumeSize(forTreeAt source: URL, clusterSize: Int = 4096) throws -> Int64 {
        requirements(`
            source 디렉터리의 내용을 copyTree로 담을 수 있는 최소 볼륨 크기의 보수적인 상한. 1 MiB 배수. (D13, P12)
            source 순회 규칙(심볼릭 링크·특수 파일은 에러)은 copyTree와 같다.
        `);
        ensure(아래 각 픽스처 T에 대해: 크기 = estimatedVolumeSize(T)인 파일 생성 → format → copyTree(T)가 성공한다);
        //      픽스처: 빈 디렉터리 / 4 KiB 미만 파일 5000개 / 1 MiB~64 MiB 파일 몇 개 / 깊이 20 디렉터리 / 한글 이름 포함
        ensure(estimatedVolumeSize(T) % (1 << 20) == 0);
        ensure(estimatedVolumeSize(T) - contentBytes(T) <= contentBytes(T) / 33 + 96 * (1 << 20), "쓸데없이 크지 않다");
    }

    imagine public init(path: String, mode: Mode) throws {
        requirements(`ntfs_mount. P5의 플래그 규칙. 실패는 posix(operation: "mount", ...).`);
        ensure(포맷하지 않은 0으로 채운 파일 → throws);
    }

    imagine public func createDirectory(_ path: String, times: NTFSFileTimes? = nil) throws {
        requirements(`부모는 존재해야 한다 (P8). D12, D14, P3 검사. times가 있으면 생성 후 설정한다.`);
        ensure(createDirectory("/a") 후 contentsOfDirectory("/") == [.init(name: "a", kind: .directory)]);
        ensure(createDirectory("/a/b") (부모 /a 없음) → throws notFound("/a"));
        ensure(createDirectory("/Sources") 후 createDirectory("/sources") → throws alreadyExists, "P3");
        ensure(createDirectory("/CON") → throws invalidName);
        ensure(createDirectory("/a.") → throws invalidName);
        ensure(createDirectory("/a ") → throws invalidName);
        ensure(createDirectory("a") → throws invalidPath);
        ensure(createDirectory("/a//b") → throws invalidPath);
        ensure(readOnly 볼륨에서 createDirectory → throws readOnlyVolume);
    }

    imagine public func writeFile(_ path: String, from source: URL, times: NTFSFileTimes? = nil,
                                  progress: ((Int64) throws -> Void)? = nil) throws {
        requirements(`
            source를 8 MiB 청크로 읽어 쓴다 (P8). progress에는 누적 바이트를 넘긴다.
            데이터를 다 쓴 뒤에 times를 설정한다 (C8).
        `);
        ensure(20 MiB + 12345 바이트 파일을 쓰고 다시 마운트해 readFile로 읽으면 바이트 단위로 같다);
        ensure(progress에 넘어온 마지막 값 == 원본 크기이고 값이 단조 증가한다);
        ensure(progress가 CancellationError를 throw하면 writeFile이 CancellationError를 throw한다);
        ensure(times를 주면 재마운트 후 attributesOfItem(path).times가 100 ns 정밀도에서 같다);
        ensure(같은 경로에 두 번 → 두 번째가 throws alreadyExists, "D14");
        ensure(이름 "한글 파일.txt"로 쓰고 재마운트 후 contentsOfDirectory에 같은 문자열로 나온다, "C5");
    }

    imagine public func writeFile(_ path: String, contents: [UInt8], times: NTFSFileTimes? = nil) throws {
        requirements(`메모리의 작은 파일용. 규칙은 위와 같다. 빈 배열이면 크기 0 파일.`);
        ensure(contents: [] → attributesOfItem(path).size == 0);
    }

    imagine public func copyTree(from source: URL, to destination: String = "/",
                                 progress: ((NTFSCopyProgress) throws -> Void)? = nil) throws -> NTFSCopySummary {
        requirements(`
            source 디렉터리의 "내용"을 이미 존재하는 destination 디렉터리 안으로 복사한다 (cp -R src/. dst 와 같은 의미).
            먼저 전체를 훑어 totalBytes를 구한다. 이름순으로 결정적인 순서로 복사한다.
            파일과 디렉터리의 시각을 P9 매핑으로 옮긴다. 디렉터리 시각은 그 안의 항목을 다 만든 뒤에 설정한다 (C8).
            심볼릭 링크, 특수 파일 → unsupportedFileType (D15). 부분 복사 상태를 되돌리지 않는다.
        `);
        ensure(픽스처 트리를 복사하고 재마운트해서 전체 트리(이름, 종류, 크기, 내용, modification 시각)가 원본과 같다);
        ensure(summary.files, summary.directories, summary.bytes가 원본 집계와 같다);
        ensure(원본에 심볼릭 링크가 있으면 → throws unsupportedFileType);
        ensure(원본에 FIFO(mkfifo)가 있으면 → throws unsupportedFileType);
        // hint: 대소문자 충돌(P3)은 createDirectory의 ensure로 검증한다. 호스트 APFS가 대소문자를 구분하지 않아 copyTree 픽스처로는 만들 수 없다.
    }

    imagine public func contentsOfDirectory(_ path: String) throws -> [NTFSDirectoryEntry] {
        requirements(`P11의 필터와 정렬.`);
        ensure(방금 포맷한 볼륨의 contentsOfDirectory("/") == [], "$MFT, ., .. 가 없다");
        ensure(파일 경로에 대해 → throws notADirectory);
    }

    imagine public func attributesOfItem(_ path: String) throws -> NTFSItemAttributes
    //      ensure는 writeFile과 copyTree 쪽에서 검증된다. 디렉터리의 size는 0이다.

    imagine public func readFile(_ path: String, into buffer: UnsafeMutableRawBufferPointer, at offset: Int64) throws -> Int {
        requirements(`offset부터 최대 buffer.count 바이트를 읽고 읽은 바이트 수를 돌려준다. EOF이면 0.`);
        ensure(크기 N 파일에서 readFile(at: N) == 0);
        ensure(디렉터리에 readFile → throws isADirectory);
    }

    imagine public func close() throws {
        requirements(`P5. ntfs_umount가 실패해도 볼륨은 해제된 것으로 취급한다 (F13, C7).`);
        ensure(close() 두 번 → 두 번째는 아무 일도 하지 않는다);
        ensure(close() 후 contentsOfDirectory("/") → throws volumeClosed);
    }
}
